class Solution {
    public int climbStairs(int n) {
        int[] dp = new int[n + 1];
        dp[0] = 1;
        dp[1] = 1;
        for (int i = 2; i <= n; i++) {
            dp[i] = dp[i - 1] + dp[i - 2];
        }
        return dp[n];
    }
}

class Solution {
    public int climbStairs(int n) {
        int twoStepsBefore = 1;
        int oneStepBefore = 1;
        for (int step = 2; step <= n; step++) {
            int current = oneStepBefore + twoStepsBefore;
            twoStepsBefore = oneStepBefore;
            oneStepBefore = current;
        }
        return oneStepBefore;
    }
}

class Solution {
    public int climbStairs(int n) {
        int[] memo = new int[n + 1];
        return ways(n, memo);
    }

    private int ways(int stepsLeft, int[] memo) {
        if (stepsLeft == 0) {
            return 1;
        }
        if (stepsLeft < 0) {
            return 0;
        }
        if (memo[stepsLeft] != 0) {
            return memo[stepsLeft];
        }
        memo[stepsLeft] = ways(stepsLeft - 1, memo) + ways(stepsLeft - 2, memo);
        return memo[stepsLeft];
    }
}

class Solution {
    public int climbStairs(int n) {
        long total = 0;
        for (int twos = 0; twos <= n / 2; twos++) {
            int ones = n - 2 * twos;
            int moves = ones + twos;
            total += choose(moves, twos);
        }
        return (int) total;
    }

    private long choose(int n, int k) {
        k = Math.min(k, n - k);
        long result = 1;
        for (int i = 1; i <= k; i++) {
            result = result * (n - k + i) / i;
        }
        return result;
    }
}

class Solution {
    public int climbStairs(int n) {
        return (int) fibonacci(n + 1)[0];
    }

    private long[] fibonacci(int index) {
        if (index == 0) {
            return new long[] {0, 1};
        }
        long[] half = fibonacci(index / 2);
        long a = half[0];
        long b = half[1];
        long c = a * (2 * b - a);
        long d = a * a + b * b;
        if (index % 2 == 0) {
            return new long[] {c, d};
        }
        return new long[] {d, c + d};
    }
}
